existingNativeGate.literal:
\if :{?invoice_presentation_active_work}
  select pg_catalog.set_config('cloudtms.managed.invoice_active_work', :'invoice_presentation_active_work', false);
  do $gate$ begin if pg_catalog.current_setting('cloudtms.managed.invoice_active_work')::boolean
    then raise exception 'CLOUDTMS_INVOICE_INSTALL_DEFERRED_ACTIVE_WORK'; end if; end $gate$;
\else
  do $gate$ begin raise exception 'CLOUDTMS_INVOICE_INSTALL_GATE_MISSING'; end $gate$;
\endif

doCalls.sql:
do $acl$
begin
  if exists (
    select 1 from pg_catalog.pg_roles where rolname='authenticator'
  ) then
    execute 'revoke all on function public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid) from authenticator';
  end if;
  if exists (
    select 1 from pg_catalog.pg_roles where rolname='supabase_admin'
  ) then
    execute 'revoke all on function public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid) from supabase_admin';
  end if;
end;
$acl$;

do $verify_acl$
begin
  if has_function_privilege(
       'anon',
       'public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid)',
       'EXECUTE'
     )
     or has_function_privilege(
       'authenticated',
       'public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid)',
       'EXECUTE'
     )
     or not has_function_privilege(
       'service_role',
       'public.timesheet_qr_refuse_and_reset(uuid,uuid,text,uuid)',
       'EXECUTE'
     ) then
    raise exception 'TIMESHEET_QR_REFUSE_SERVICE_ACL_INVALID';
  end if;
end;
$verify_acl$;

DO $do$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'anon') THEN
    EXECUTE 'REVOKE ALL ON FUNCTION public.contract_week_delete_planned(uuid, uuid) FROM anon';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'authenticated') THEN
    EXECUTE 'REVOKE ALL ON FUNCTION public.contract_week_delete_planned(uuid, uuid) FROM authenticated';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'service_role') THEN
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.contract_week_delete_planned(uuid, uuid) TO service_role';
  END IF;
END
$do$;

do $grants$
begin
  if exists(select 1 from pg_roles where rolname='anon') then
    revoke all on function public.candidate_daily_legacy_availability_apply_atomic_v1(
      jsonb,text,uuid,text,jsonb,text
    ) from anon;
  end if;
  if exists(select 1 from pg_roles where rolname='authenticated') then
    revoke all on function public.candidate_daily_legacy_availability_apply_atomic_v1(
      jsonb,text,uuid,text,jsonb,text
    ) from authenticated;
  end if;
  if exists(select 1 from pg_roles where rolname='service_role') then
    grant execute on function public.candidate_daily_legacy_availability_apply_atomic_v1(
      jsonb,text,uuid,text,jsonb,text
    ) to service_role;
  end if;
end;
$grants$;

do $grants$
begin
  if exists(select 1 from pg_roles where rolname='anon') then
    revoke all on function public.candidate_daily_reconciliation_apply_atomic_v1(jsonb,uuid,text,jsonb,text) from anon;
  end if;
  if exists(select 1 from pg_roles where rolname='authenticated') then
    revoke all on function public.candidate_daily_reconciliation_apply_atomic_v1(jsonb,uuid,text,jsonb,text) from authenticated;
  end if;
  if exists(select 1 from pg_roles where rolname='service_role') then
    grant execute on function public.candidate_daily_reconciliation_apply_atomic_v1(jsonb,uuid,text,jsonb,text) to service_role;
  end if;
end;
$grants$;
